    // 实际运行时可使用 empty_like 修改为输出shape推断后的张量
    auto B = x.size(0);
    auto Cin = x.size(1);
    auto Lin = x.size(2);
    auto Cout = w.size(0);
    auto K = w.size(2);
    auto Lout = Lin - K + 1;
    at::Tensor y = at::empty({B, Cout, Lout}, x.options());
    EXEC_NPU_CMD(aclnnConvStandard1dCustom, x, w, y);
    return y;
}

